        @import url('https://fonts.googleapis.com/css2?family=Dancing+Script:wght@700&family=Montserrat:wght@500;700;800&display=swap');

        /* 声明并载入开源汇文明朝体 */
        @font-face {
            font-family: 'Huiwen Mincho';
            src: url('https://testingcf.jsdelivr.net/gh/ctg-font/HuiwenMincho@master/HuiwenMincho.otf') format('opentype'),
                 url('https://cdn.jsdelivr.net/gh/ctg-font/HuiwenMincho@master/HuiwenMincho.otf') format('opentype');
            font-display: swap;
        }

        /* --- 1. 画报专色设计系统 --- */
        :root {
            --font-serif: 'Source Han Serif CN', 'Source Han Serif SC', 'Noto Serif CJK SC', '思源宋体', 'Songti SC', 'SimSun', serif;
            --font-sans: 'Montserrat', -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
            --font-script: 'Dancing Script', cursive;
            --font-poetic: 'Huiwen-MinchoGBK', var(--font-serif);
            --font-title: 'Maoken Glitch Serif', var(--font-serif);

            /* 昼间：赤红印记 + 暖阳金砂 */
            --day-accent: #b32c2c;
            --day-sub-accent: #d4a373;
            --day-txt-primary: #1c1c1e;
            --day-txt-secondary: #3a3a3c;
            --day-txt-muted: #8e8e93;
            --day-border: rgba(28, 28, 30, 0.09);
            --day-axis: rgba(28, 28, 30, 0.04);
            --day-card: rgba(255, 255, 255, 0.8);

            /* 夜间：冷翠星蓝 + 银辉月影 */
            --night-accent: #2e86de;
            --night-sub-accent: #8ca6db;
            --night-txt-primary: #f5f6fa;
            --night-txt-secondary: #dcdde1;
            --night-txt-muted: #718093;
            --night-border: rgba(245, 246, 250, 0.09);
            --night-axis: rgba(245, 246, 250, 0.04);
            --night-card: rgba(28, 28, 30, 0.8);

            --transition-base: all 0.5s cubic-bezier(0.16, 1, 0.3, 1);
        }

        /* --- 2. 凝聚态布局外壳 --- */
        .st-editorial-bar {
            width: 100%;
            max-width: 580px;
            margin: 16px auto;
            padding: clamp(20px, 6cqw, 40px);
            box-sizing: border-box;
            background: transparent !important;
            border: none !important;
            box-shadow: none !important;
            display: flex;
            flex-direction: column;
            gap: 26px;
            font-family: var(--font-serif);
            font-size: 17px;
            line-height: 1.8;
            transition: var(--transition-base);
            position: relative;
            container-type: inline-size;
            user-select: none;
            opacity: 0;
            animation: bar-fade-in 1.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }

        @keyframes bar-fade-in {
            from {
                opacity: 0;
                transform: translateY(12px);
                filter: blur(6px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
                filter: blur(0);
            }
        }

        .st-hero-grid, .st-anchor-row, .st-book-title-block, .st-poetic-bar-container, .st-editorial-footer {
            position: relative;
            z-index: 2;
        }

        /* 主题绑定变量 */
        .theme-day {
            --accent: var(--day-accent);
            --sub-accent: var(--day-sub-accent);
            --txt-primary: var(--day-txt-primary);
            --txt-secondary: var(--day-txt-secondary);
            --txt-muted: var(--day-txt-muted);
            --border-line: var(--day-border);
            --axis-line: var(--day-axis);
            --card-bg: var(--day-card);
        }

        .theme-night {
            --accent: var(--night-accent);
            --sub-accent: var(--night-sub-accent);
            --txt-primary: var(--night-txt-primary);
            --txt-secondary: var(--night-txt-secondary);
            --txt-muted: var(--night-txt-muted);
            --border-line: var(--night-border);
            --axis-line: var(--night-axis);
            --card-bg: var(--night-card);
        }

        /* --- 3. 顶置 Hero 非对称网格 --- */
        .st-hero-grid {
            display: grid;
            grid-template-columns: 1fr 120px;
            align-items: center;
            gap: 28px;
            width: 100%;
        }

        .st-hero-left {
            display: flex;
            flex-direction: column;
            align-items: flex-start;
            text-align: left;
            position: relative;
            width: 100%;
        }

        /* 潇洒飘逸手写大字 */
        .st-hero-script {
            font-family: var(--font-script);
            font-size: clamp(52px, 10cqw, 68px);
            line-height: 0.8;
            color: var(--accent);
            opacity: 0.95;
            transition: var(--transition-base);
            position: relative;
            z-index: 2;
        }

        .theme-day .st-hero-script {
            animation: accent-glow-day 6s ease-in-out infinite;
        }
        .theme-night .st-hero-script {
            animation: accent-glow-night 6s ease-in-out infinite;
        }

        /* 暖沙金副标题 */
        .st-hero-subtitle {
            font-family: var(--font-sans);
            font-size: clamp(12px, 2.2cqw, 14px);
            font-weight: 800;
            letter-spacing: 2.5px;
            color: var(--sub-accent);
            text-transform: uppercase;
            margin-top: 6px;
            position: relative;
            z-index: 2;
            transition: var(--transition-base);
        }

        /* 移入正文下方的小号精致编号 */
        .st-quote-watermark {
            font-family: var(--font-sans);
            font-size: 11px;
            font-weight: 700;
            letter-spacing: 3px;
            color: var(--accent);
            opacity: 0.7;
            margin-top: 8px;
            text-transform: uppercase;
            transition: var(--transition-base);
        }

        /* 纯白描文学摘抄 */
        .st-hero-quote {
            font-size: clamp(14px, 2.2cqw, 16px);
            color: var(--txt-secondary);
            line-height: 1.8;
            font-style: italic;
            margin-top: 14px;
            position: relative;
            z-index: 2;
            text-shadow: none;
            padding-left: 28px;
        }

        /* 引号视觉优化：向左外侧悬挂避让，保持绝对安全间距 */
        .st-hero-quote::before {
            content: '“';
            font-family: var(--font-serif);
            font-size: 28px;
            font-weight: 700;
            color: var(--accent);
            position: absolute;
            left: -10px;
            top: -0.32em;
            transition: var(--transition-base);
        }

        .st-hero-author {
            display: block;
            font-size: 12px;
            color: var(--txt-muted);
            font-style: normal;
            margin-top: 5px;
            font-family: var(--font-serif);
        }

        /* --- 4. 仿黑胶唱片专辑旋转封面 + 配重唱针 --- */
        .st-hero-right {
            position: relative;
            width: 120px;
            height: 120px;
            box-sizing: border-box;
            background: transparent;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: var(--transition-base);
        }

        /* 精简双同心圆极简黑胶盘 */
        .st-vinyl-record {
            width: 110px;
            height: 110px;
            border-radius: 50%;
            background: #0d0d0d;
            border: 1.5px solid rgba(255, 255, 255, 0.08);
            box-shadow:
                0 6px 16px rgba(0, 0, 0, 0.35),
                inset 0 0 0 1.5px rgba(255, 255, 255, 0.06),
                inset 0 0 0 5px #0d0d0d,
                inset 0 0 0 6px rgba(255, 255, 255, 0.04);
            position: relative;
            overflow: hidden;
            display: flex;
            align-items: center;
            justify-content: center;
            animation: st-spin 14s linear infinite;
            transition: var(--transition-base);
            z-index: 1;
        }

        /* 专辑大图化剪裁区 */
        .st-stamp-clipper {
            width: 76%;
            height: 76%;
            border-radius: 50%;
            overflow: hidden;
            position: relative;
            border: 1px solid #000;
            z-index: 2;
        }

        .st-dynamic-img {
            width: 100%;
            height: 100%;
            background-size: cover;
            background-position: center;
            display: block;
            transform: scale(1.05);
            transition: opacity 0.5s ease;
        }

        /* 金属拟真唱针 */
        .st-tonearm {
            position: absolute;
            top: -2px;
            right: 12px;
            width: 32px;
            height: 65px;
            z-index: 10;
            pointer-events: none;
            transform-origin: 24px 8px;
            transform: rotate(0deg);
            transition: transform 0.6s cubic-bezier(0.25, 1, 0.5, 1);
        }

        /* 触碰唱机时，唱针偏转搭上轨道 */
        .st-hero-right:hover .st-tonearm {
            transform: rotate(18deg);
        }

        @keyframes st-spin {
            from { transform: rotate(0deg); }
            to { transform: rotate(360deg); }
        }

        /* --- 5. 中层排版轴位置调换 (Weather | Relation | Location) --- */
        .st-anchor-row {
            display: grid;
            grid-template-columns: 1fr auto 1fr;
            align-items: center;
            border-bottom: 1px solid var(--border-line);
            padding-bottom: 14px;
            margin-top: 6px;
        }

        .st-anchor-col {
            font-family: var(--font-sans);
            font-size: clamp(11px, 2cqw, 13px);
            font-weight: 700;
            letter-spacing: 1px;
            color: var(--txt-muted);
            text-transform: uppercase;
        }

        /* 左列：诗意天气 */
        .st-anchor-col.left {
            text-align: left;
            color: var(--sub-accent);
            font-family: var(--font-serif);
            font-weight: 700;
            display: flex;
            align-items: center;
            gap: 5px;
        }

        /* 中列：角色名 X 用户名 */
        .st-anchor-col.center {
            text-align: center;
            font-family: var(--font-serif);
            font-weight: 700;
            color: var(--txt-primary);
        }

        /* 右列：地理定位 */
        .st-anchor-col.right {
            text-align: right;
            font-family: var(--font-serif);
            font-weight: 400;
            color: var(--txt-secondary);
        }

        /* --- 6. 下层书名号与纵向竖线箴言 --- */
        .st-book-title-block {
            font-size: clamp(28px, 4cqw, 36px);
            font-weight: normal; /* 毛垦故障宋体自带美学设计感，无需二次机械加粗 */
            color: var(--accent);
            text-align: center;
            letter-spacing: 2.5px;
            margin-top: 10px;
            font-family: var(--font-title);
            transition: var(--transition-base);
        }

        /* 竖线精致箴言排版 */
        .st-poetic-bar-container {
            width: 100%;
            display: flex;
            flex-direction: column; /* 纵向排布支撑多行单独居中对齐 */
            align-items: center;
            justify-content: center;
            gap: 10px; /* 纵向行间距 */
            font-size: clamp(16px, 2.4cqw, 19px);
            color: var(--txt-primary);
            line-height: 1.6;
            letter-spacing: 1.5px;
            text-align: center;
            transition: var(--transition-base);
            font-family: var(--font-poetic);
            font-weight: normal;
        }

        .st-poetic-line {
            display: block;
            width: 100%;
            text-align: center; /* 确保多行状态下每行单独物理居中 */
            word-break: break-all;
        }

        /* --- 7. 频谱底部对齐可视化波形分割线 --- */
        .st-visualizer-divider {
            width: 100%;
            height: 18px;
            display: flex;
            align-items: flex-end; /* 底部绝对固定对齐 */
            justify-content: center;
            gap: 3px; /* 间距微调，使30柱紧凑排布 */
            margin-top: 8px;
            border-bottom: 1px solid var(--border-line);
            padding-bottom: 0; /* 移除底部内边距，使波形底轴紧密贴合 */
            box-sizing: content-box;
        }

        .st-vis-bar {
            width: 3.5px; /* 加宽频谱柱，视觉效果更具实体质感 */
            height: 2px; /* 初始底部锚定高度 */
            background-color: var(--txt-muted);
            border-radius: 1.5px; /* 同步微调圆角，保持胶囊边缘温润感 */
            opacity: 0.45;
            transform-origin: bottom; /* 动画起点设定在底部 */
            transition: var(--transition-base);
        }

        /* 30个频谱柱的高低交错与平滑波动波形 */
        .st-vis-bar:nth-child(10n+1) { animation: st-bounce-up 1.0s ease-in-out infinite alternate; animation-delay: 0.1s; }
        .st-vis-bar:nth-child(10n+2) { animation: st-bounce-up 1.4s ease-in-out infinite alternate; animation-delay: 0.3s; }
        .st-vis-bar:nth-child(10n+3) { animation: st-bounce-up 0.8s ease-in-out infinite alternate; animation-delay: 0.0s; }
        .st-vis-bar:nth-child(10n+4) { animation: st-bounce-up 1.2s ease-in-out infinite alternate; animation-delay: 0.5s; }
        .st-vis-bar:nth-child(10n+5) { animation: st-bounce-up 0.9s ease-in-out infinite alternate; animation-delay: 0.2s; }
        .st-vis-bar:nth-child(10n+6) { animation: st-bounce-up 1.5s ease-in-out infinite alternate; animation-delay: 0.4s; }
        .st-vis-bar:nth-child(10n+7) { animation: st-bounce-up 1.1s ease-in-out infinite alternate; animation-delay: 0.15s; }
        .st-vis-bar:nth-child(10n+8) { animation: st-bounce-up 1.3s ease-in-out infinite alternate; animation-delay: 0.6s; }
        .st-vis-bar:nth-child(10n+9) { animation: st-bounce-up 0.7s ease-in-out infinite alternate; animation-delay: 0.35s; }
        .st-vis-bar:nth-child(10n+10) { animation: st-bounce-up 1.2s ease-in-out infinite alternate; animation-delay: 0.25s; }

        @keyframes st-bounce-up {
            0% { height: 2px; }
            100% { height: 16px; } /* 顶部向上生发高度 */
        }

        /* --- 8. 页脚与极简控制器 --- */
        .st-editorial-footer {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-top: 4px;
            padding-top: 4px;
        }

        /* 极简控制器 */
        .st-astrolabe-control {
            display: flex;
            align-items: center;
            gap: 6px;
            cursor: pointer;
            padding: 4px 10px;
            border-radius: 12px;
            background: var(--axis-line);
            border: 1px solid var(--border-line);
            font-family: var(--font-sans);
            font-size: 10px;
            font-weight: 700;
            letter-spacing: 1px;
            color: var(--txt-secondary);
            transition: var(--transition-base);
        }

        .st-astrolabe-control:hover {
            color: var(--accent);
            border-color: var(--accent);
            transform: translateY(-1px);
        }

        .st-chronos-clock {
            font-size: clamp(11px, 2cqw, 13px);
            font-weight: 600; /* 字体加粗处理，强化读数清晰度 */
            color: var(--txt-muted);
            display: flex;
            align-items: center;
            gap: 6px;
        }

        /* --- 9. 单色同谱深浅呼吸 --- */
        @keyframes accent-glow-day {
            0%, 100% { color: rgba(179, 44, 44, 1); }
            50% { color: rgba(179, 44, 44, 0.45); }
        }

        @keyframes accent-glow-night {
            0%, 100% { color: rgba(46, 134, 222, 1); }
            50% { color: rgba(46, 134, 222, 0.45); }
        }

        /* --- 10. 移动端自适应布局形态切换 --- */
        @container (max-width: 480px) {
            .st-hero-grid {
                grid-template-columns: 1fr;
                gap: 24px;
                justify-items: center;
            }
            .st-hero-left {
                align-items: center;
                text-align: center;
            }
            .st-hero-right {
                width: 110px;
                height: 110px;
            }
            .st-anchor-row {
                grid-template-columns: 1fr;
                gap: 8px;
                justify-items: center;
                text-align: center;
            }
            .st-anchor-col.left, .st-anchor-col.center, .st-anchor-col.right {
                text-align: center;
                justify-content: center;
            }
        }
    </style>
</head>
<body>
    <!-- 数据注入槽（采用pre标签严格保留原始换行与格式） -->
    <pre id="status-raw-data" style="display: none;">$1</pre>

    <div class="st-editorial-bar theme-day" id="status-bar-shell">
        <!-- 垂直垂直雨幕Canvas层 -->
        <canvas id="st-particle-canvas" style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; z-index: 0;"></canvas>

        <!-- 1. Hero Block: 非对称网格、唱针黑胶与手写体 -->
        <div class="st-hero-grid">
            <div class="st-hero-left">
                <!-- 飘逸手写大字 -->
                <div class="st-hero-script" id="st-render-en">Nostalgia</div>
                <!-- 暖沙金副标题 -->
                <div class="st-hero-subtitle" id="st-render-sub">THE AFTERGLOW OF A SILENT WORLD</div>
                <!-- 小号编号移入手写体下方 -->
                <div class="st-quote-watermark" id="st-render-watermark">NO.01</div>
                <!-- 纯白描文学摘抄 -->
                <div class="st-hero-quote" id="st-render-quote">
                    时间正在碎裂的镜中沉睡。
                    <span class="st-hero-author" id="st-render-author">— 佚名</span>
                </div>
            </div>

            <!-- 右侧仿黑胶唱片专辑旋转封面与唱针 -->
            <div class="st-hero-right">
                <!-- 金属唱针 -->
                <div class="st-tonearm">
                    <svg viewBox="0 0 32 65" fill="none" xmlns="http://www.w3.org/2000/svg" style="width: 100%; height: 100%;">
                        <!-- 唱针配重转轴 -->
                        <circle cx="24" cy="8" r="6" fill="#888" stroke="#444" stroke-width="1.5"/>
                        <circle cx="24" cy="8" r="2" fill="#222"/>
                        <!-- 针臂 -->
                        <path d="M24 14 L24 38 L14 52" stroke="#aaa" stroke-width="2" stroke-linecap="round"/>
                        <!-- 针头与抬针手柄 -->
                        <rect x="10" y="50" width="8" height="5" rx="1.5" fill="#333" transform="rotate(-15 14 52)"/>
                        <path d="M10 52 L6 50" stroke="#888" stroke-width="1"/>
                    </svg>
                </div>
                <!-- 黑胶盘（中心剪裁区完美兼容酒馆原生头像类） -->
                <div class="st-vinyl-record">
                    <div class="st-stamp-clipper">
                        <div class="char-avatar st-dynamic-img" id="st-dynamic-image"></div>
                    </div>
                </div>
            </div>
        </div>

        <!-- 2. 中层排版轴位置重组 (Weather | Relation | Location) -->
        <div class="st-anchor-row">
            <!-- 左侧：诗意天气 -->
            <div class="st-anchor-col left" id="st-render-weather">
                薄暮微雨浓
            </div>
            <!-- 中间：角色名 X 用户名 -->
            <div class="st-anchor-col center" id="st-render-relation">
                CHAR X USER
            </div>
            <!-- 右侧：地理定位 -->
            <div class="st-anchor-col right" id="st-render-location">
                东湖之畔 · 临水栈道
            </div>
        </div>

        <!-- 3. 书名号 -->
        <div class="st-book-title-block">
            <div class="st-book-bracket">《<span id="st-render-title">落日余晖</span>》</div>
        </div>

        <!-- 4. 纵向中式诗词箴言 (Huiwen Mincho 字体支撑) -->
        <div class="st-poetic-bar-container" id="st-render-poem">
            <span class="st-poetic-line">每个漂泊的灵魂</span>
            <span class="st-poetic-line">终将迎来自己的神明</span>
        </div>

        <!-- 5. 音频波形跳动分割线（30柱声谱绵密矩阵） -->
        <div class="st-visualizer-divider">
            <div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div>
            <div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div>
            <div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div>
            <div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div>
            <div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div>
            <div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div><div class="st-vis-bar"></div>
        </div>

        <!-- 6. 页脚与极简控制器 -->
        <div class="st-editorial-footer">
            <div class="st-astrolabe-control" id="st-theme-btn">
                <i class="fas fa-sun" id="st-theme-icon"></i>
                <span id="st-theme-label">AMATERASU</span>
            </div>
            <div class="st-chronos-clock">
                <span id="st-render-time">2025/10/27 星期一 05:40 PM</span>
            </div>
        </div>
    </div>

    <script>
        (function() {
            const shell = document.getElementById('status-bar-shell');
            const themeBtn = document.getElementById('st-theme-btn');
            const themeIcon = document.getElementById('st-theme-icon');
            const themeLabel = document.getElementById('st-theme-label');

            // --- 1. 天照与月读模式切换 ---
            function applyTheme(theme) {
                if (theme === 'night') {
                    shell.classList.remove('theme-day');
                    shell.classList.add('theme-night');
                    themeIcon.className = 'fas fa-moon';
                    themeLabel.textContent = 'TSUKUYOMI';
                } else {
                    shell.classList.remove('theme-night');
                    shell.classList.add('theme-day');
                    themeIcon.className = 'fas fa-sun';
                    themeLabel.textContent = 'AMATERASU';
                }
            }

            let savedTheme = localStorage.getItem('sillytavern_statusbar_theme') || 'night';
            applyTheme(savedTheme);

            themeBtn.addEventListener('click', function() {
                let currentTheme = shell.classList.contains('theme-night') ? 'night' : 'day';
                let nextTheme = currentTheme === 'night' ? 'day' : 'night';
                localStorage.setItem('sillytavern_statusbar_theme', nextTheme);
                applyTheme(nextTheme);
            });

            // --- 3. Canvas 垂直雨幕物理特效 ---
            (function() {
                const canvas = document.getElementById('st-particle-canvas');
                if (!canvas) return;
                const ctx = canvas.getContext('2d');
                let w = canvas.width = canvas.parentNode.offsetWidth;
                let h = canvas.height = canvas.parentNode.offsetHeight;
                const pArr = [];

                // 初始化25根垂直下落的细灰色雨丝
                for (let i = 0; i < 25; i++) {
                    pArr.push({
                        x: Math.random() * w,
                        y: Math.random() * h,
                        l: Math.random() * 12 + 6,
                        vy: Math.random() * 3.5 + 2.5,
                        a: Math.random() * 0.28 + 0.12
                    });
                }

                function drawRain() {
                    ctx.clearRect(0, 0, w, h);
                    ctx.lineWidth = 1;

                    pArr.forEach(p => {
                        p.y += p.vy;

                        if (p.y > h) {
                            p.y = -p.l;
                            p.x = Math.random() * w;
                        }

                        ctx.beginPath();
                        ctx.strokeStyle = `rgba(180, 180, 180, ${p.a})`;
                        ctx.moveTo(p.x, p.y);
                        ctx.lineTo(p.x, p.y + p.l);
                        ctx.stroke();
                    });
                    requestAnimationFrame(drawRain);
                }

                window.addEventListener('resize', () => {
                    w = canvas.width = canvas.parentNode.offsetWidth;
                    h = canvas.height = canvas.parentNode.offsetHeight;
                });
                drawRain();
            })();

            // --- 4. 括号解构器 ---
            function extractBlocks(text) {
                text = text.replace(/^[\s\S]*<\/(?:think|thinking)>/i, '').trim();
                const blocks = [];
                let currentBlock = "";
                let depth = 0;
                for (let i = 0; i < text.length; i++) {
                    const char = text[i];
                    if (char === '[') {
                        if (depth > 0) currentBlock += char;
                        depth++;
                    } else if (char === ']') {
                        depth--;
                        if (depth === 0) {
                            if (currentBlock.trim()) blocks.push(currentBlock);
                            currentBlock = "";
                        } else if (depth > 0) {
                            currentBlock += char;
                        } else { depth = 0; }
                    } else {
                        if (depth > 0) currentBlock += char;
                    }
                }
                if (depth > 0 && currentBlock.trim()) blocks.push(currentBlock);
                return blocks;
            }

            // --- 5. 智能解析与渲染 ---
            try {
                const rawData = document.getElementById('status-raw-data').textContent;
                const blocks = extractBlocks(rawData);

                let parsed = {
                    title: '未定叙事',
                    seq: '01',
                    time: '----/--/-- 星期- --:-- --',
                    loc: '世界边缘 · 某个维度',
                    relation: 'CHAR X USER',
                    weather: '薄暮微雨',
                    quote: '世界上只有一种英雄主义。',
                    author: '罗曼·罗兰',
                    poem: '当前分歧静默，叙事齿轮待续。'
                };

                blocks.forEach(b => {
                    const parts = b.split('|').map(s => s.trim());
                    if (parts.length < 2) return;
                    const header = parts[0].toLowerCase();

                    if (header === 'title') {
                        parsed.title = parts[1] || parsed.title;
                    } else if (header === 'seq') {
                        parsed.seq = parts[1] ? 'No.' + parts[1] : parsed.seq;
                    } else if (header === 'time') {
                        parsed.time = parts[1] || parsed.time;
                    } else if (header === 'loc') {
                        parsed.loc = parts.slice(1).join(' · ');
                    } else if (header === 'relation') {
                        parsed.relation = `${parts[1]} X ${parts[2]}`;
                    } else if (header === 'weather') {
                        // 4-6 字天气强制安全截取，防溢出
                        parsed.weather = (parts[1] || parsed.weather).substring(0, 6);
                    } else if (header === 'quote') {
                        const rawQuote = (parts[1] || '').replace(/[“”"'「」]/g, '').trim();
                        const authorSplit = rawQuote.split('——');
                        if (authorSplit.length > 1) {
                            parsed.quote = authorSplit[0].trim();
                            parsed.author = '— ' + authorSplit[1].trim();
                        } else {
                            parsed.quote = rawQuote;
                            parsed.author = '';
                        }
                    } else if (header === 'poem') {
                        parsed.poem = parts.slice(1).join('\n');
                    }
                });

                // 更新 DOM 节点数据
                document.getElementById('st-render-title').textContent = parsed.title;
                document.getElementById('st-render-watermark').textContent = parsed.seq.toUpperCase();
                document.getElementById('st-render-time').textContent = parsed.time;
                document.getElementById('st-render-relation').textContent = parsed.relation;
                document.getElementById('st-render-weather').textContent = parsed.weather;
                document.getElementById('st-render-location').textContent = parsed.loc;

                // 配套序号自动计算契合的英标手写词
                const enWords = ["Nostalgia", "Requiem", "Solitude", "Melancholy", "Eternity", "Oblivion"];
                const wordIndex = parseInt(parsed.seq.replace(/\D/g, '')) || 0;
                const scriptText = enWords[wordIndex % enWords.length];
                document.getElementById('st-render-en').textContent = scriptText;
                document.getElementById('st-render-sub').textContent = "THE AFTERGLOW OF " + scriptText.toUpperCase();

                // 渲染文学摘抄
                const quoteTextNode = document.getElementById('st-render-quote');
                if (parsed.author) {
                    quoteTextNode.innerHTML = `${parsed.quote}<span class="st-hero-author">${parsed.author}</span>`;
                } else {
                    quoteTextNode.textContent = parsed.quote;
                }

                // 智能分句并两两合并（每两句断一次换行，行内以宽空格呼吸留白）
                const rawLines = parsed.poem.split(/[\n\r,，。|｜]/).map(line => line.trim()).filter(line => line.length > 0);
                const combinedLines = [];
                for (let i = 0; i < rawLines.length; i += 2) {
                    if (i + 1 < rawLines.length) {
                        combinedLines.push(`${rawLines[i]}&nbsp;&nbsp;&nbsp;${rawLines[i + 1]}`);
                    } else {
                        combinedLines.push(rawLines[i]);
                    }
                }
                const poemContainer = document.getElementById('st-render-poem');
                poemContainer.innerHTML = combinedLines.map(line => `<span class="st-poetic-line">${line}</span>`).join('');

                // 移除外链生图逻辑，让酒馆原生的 char-avatar 渲染完美承接

            } catch (err) {
                console.error("状态栏解析错误: ", err);
            }
        })();
    </script>
</body>
</html>
